<?php
declare(strict_types=1);namespace App\Interfaces\Http\Controllers\Api\V1\Underwriting;
use App\Application\Underwriting\{DisclosureGovernanceService,DocumentRequirementService};use App\Models\{DisclosureSchemaVersion,DocumentRequirementVersion,InsuranceLine};use Illuminate\Http\{JsonResponse,Request};
final class UnderwritingConfigurationController{public function createDisclosure(Request$r,DisclosureGovernanceService$s):JsonResponse{$d=$r->validate(['insurance_line_id'=>'required|uuid|exists:insurance_lines,id','questions'=>'required|array|min:1','effective_from'=>'required|date','effective_until'=>'nullable|date|after_or_equal:effective_from']);return response()->json(['data'=>$s->create(InsuranceLine::findOrFail($d['insurance_line_id']),$d,$r->user())],201);}public function approveDisclosure(Request$r,string$schema,DisclosureGovernanceService$s):JsonResponse{return response()->json(['data'=>$s->approve(DisclosureSchemaVersion::findOrFail($schema),$r->user())]);}public function createRequirement(Request$r,DocumentRequirementService$s):JsonResponse{$d=$r->validate(['line_code'=>'required|string|max:32|exists:insurance_lines,code','code'=>'required|string|max:64','name'=>'required|array','rules'=>'sometimes|array','mandatory'=>'required|boolean','effective_from'=>'required|date','effective_until'=>'nullable|date|after_or_equal:effective_from']);return response()->json(['data'=>$s->create($d,$r->user())],201);}public function approveRequirement(Request$r,string$requirement,DocumentRequirementService$s):JsonResponse{return response()->json(['data'=>$s->approve(DocumentRequirementVersion::findOrFail($requirement),$r->user())]);}}
